<?php
namespace Tests\Feature;
use App\Models\Alumno; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class ApiTest extends TestCase { use RefreshDatabase; public function test_api_login_returns_token_and_protects_profile(): void { $user=User::factory()->create(['role'=>'padre','password'=>'Padre1234']); $this->getJson('/api/v1/me')->assertUnauthorized(); $login=$this->postJson('/api/v1/login',['email'=>$user->email,'password'=>'Padre1234'])->assertOk()->json(); $this->withToken($login['token'])->getJson('/api/v1/me')->assertOk()->assertJsonPath('email',$user->email); } public function test_parent_api_profile_only_returns_linked_children(): void { $padre=User::factory()->create(['role'=>'padre']); $hijo=Alumno::create(['legajo'=>'API-1','dni'=>'45000001','nombre'=>'Hijo','apellido'=>'Propio','fecha_nacimiento'=>'2012-01-01','domicilio'=>'Calle']); $ajeno=Alumno::create(['legajo'=>'API-2','dni'=>'45000002','nombre'=>'Alumno','apellido'=>'Ajeno','fecha_nacimiento'=>'2012-01-01','domicilio'=>'Calle']); $padre->hijos()->attach($hijo); $token=$padre->createToken('test')->plainTextToken; $this->withToken($token)->getJson('/api/v1/me')->assertJsonFragment(['nombre'=>'Hijo'])->assertJsonMissing(['nombre'=>'Alumno']); } }
